<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$in=messenger_input();$endpoint=trim((string)($in['endpoint']??''));$keys=is_array($in['keys']??null)?$in['keys']:[];if(!filter_var($endpoint,FILTER_VALIDATE_URL)||!str_starts_with($endpoint,'https://'))throw new InvalidArgumentException('اشتراک Push معتبر نیست.');$p=MessengerSecurity::text($keys['p256dh']??'',255);$a=MessengerSecurity::text($keys['auth']??'',255);if($p===''||$a==='')throw new InvalidArgumentException('کلید اشتراک Push ناقص است.');Database::execute('INSERT INTO chat_push_subscriptions(user_id,endpoint,p256dh,auth_secret,user_agent,active,last_seen_at,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW(),NOW()) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),p256dh=VALUES(p256dh),auth_secret=VALUES(auth_secret),user_agent=VALUES(user_agent),active=1,last_seen_at=NOW(),updated_at=NOW()',[(int)$u['id'],$endpoint,$p,$a,MessengerSecurity::text($_SERVER['HTTP_USER_AGENT']??'',255)]);return ['subscribed'=>true];},true);
